 WifeMatch m;string saved,folder;bool had,restored;int errors,lastRound;readonly bool[] finishes=new bool[4];readonly StringBuilder log=new StringBuilder();void Check(bool ok,string label){log.AppendLine((ok?"PASS ":"FAIL ")+label);if(!ok)errors++;Write();}void Write(){File.WriteAllText(folder+"/progress.txt",log.ToString());}void Error(string s,string stack,LogType type){if(type==LogType.Error||type==LogType.Exception){errors++;log.AppendLine("ERROR "+s);Write();}}
