m.Clock&&penalty==first.PenaltyRemaining,"pause preserves constrained passenger clock and penalty");m.Resume();Time.timeScale=4;yield return new WaitForSeconds(5.2f);Check(first.State==WifeState.Racing&&m.Clock-clock>=5,"fixed five-second penalty elapses while other pairs continue");m.SetupScreen();m.AllBots();m.option=1;for(int i=0;i<8;i++)m.setup.players[i].difficulty=(BowlingDifficulty)(i%3);Check(m.StartMatch(),"fresh complete mixed-difficulty series starts");Time.timeScale=4;end=Time.realtimeSinceStartup+900;float next=0;bool swapped=false;while(!m.Finished&&Time.realtimeSinceStartup<end){if(m.Phase==WifePhase.RaceResult&&lastRound!=m.series.round){lastRound=m.series.round;for(int i=0;i<4;i++)finishes[i]|=m.pairs[i].State==WifeState.Finished;log.AppendLine("RACE "+lastRound+" ranks="+string.Join(",",m.series.ranks)+" drops="+string.Join(",",m.pairs.Select(pair=>pair.Drops)));}swapped|=m.Swapped;if(Time.realtimeSinceStartup>=next){File.WriteAllText(folder+"/progress.txt",log+"CURRENT race="+m.series.round+" phase="+m.Phase+" clock="+m.Clock+" states="+string.Join(",",m.pairs.Select(pair=>pair.State+":"+pair.Checkpoint+":"+pair.driver.body.position.z.ToString("F0")+":"+pair.Drops))+" errors="+errors);next=Time.realtimeSinceStartup+2;}yield return null;}
 Check(m.Finished&&m.series.completed>=3&&m.series.winner>=0,"complete physical three-race series with authoritative winner");Check(finishes.All(value=>value),"all four pairs can finish together in carried state");Check(swapped&&m.DriverRole(0)==((m.series.completed-1)%2==0?0:4)&&m.PassengerRole(0)==((m.series.completed-1)%2==0?4:0),"automatic between-race role swaps preserve identity indices across ordinary and extra races");log.AppendLine("MATCH races="+m.series.completed+" winner="+m.series.winner+" points="+string.Join(",",m.series.total)+" ERRORS="+errors+". Actual NWH/PhysX, controlled drop/retrieval reproduction and AI; no human/hardware validation.");File.WriteAllText(folder+"/result.txt",log.ToString());Debug.Log("WIFE_PROBE_COMPLETE "+log);Restore();if(!Application.isEditor)Application.Quit(errors==0?0:2);}
 void Restore(){if(restored)return;restored=true;Application.logMessageReceived-=Error;if(m!=null){m.SetupScreen();if(had)LWS.TruckSports.SportsPrefs.SetString(m.PreferenceKey,saved);else LWS.TruckSports.SportsPrefs.DeleteKey(m.PreferenceKey);LWS.TruckSports.SportsPrefs.Save();}Time.timeScale=1;}void OnDestroy(){Restore();}
